package store

import (
	"errors"
	"sync"
	"testing"

	"github.com/raahii/golang-grpc-realworld-example/model"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
)

func TestArticleStoreAddFavorite(t *testing.T) {
	tests := []struct {
		name           string
		setupMock      func(*MockDB, *MockAssociation)
		expectedError  error
		expectedCount  int32
		concurrentTest bool
	}{
		{
			name: "Successful favorite addition",
			setupMock: func(mockDB *MockDB, mockAssoc *MockAssociation) {
				mockDB.On("Model", mock.Anything).Return(mockDB)
				mockDB.On("Association", "FavoritedBy").Return(mockAssoc)
				mockAssoc.On("Append", mock.Anything).Return(nil)
				mockDB.On("Save", mock.Anything).Return(mockDB)
			},
			expectedError:  nil,
			expectedCount:  1,
			concurrentTest: false,
		},
		{
			name: "Error during favorite addition",
			setupMock: func(mockDB *MockDB, mockAssoc *MockAssociation) {
				mockDB.On("Model", mock.Anything).Return(mockDB)
				mockDB.On("Association", "FavoritedBy").Return(mockAssoc)
				mockAssoc.On("Append", mock.Anything).Return(errors.New("database error"))
			},
			expectedError:  errors.New("database error"),
			expectedCount:  0,
			concurrentTest: false,
		},
		{
			name: "Concurrent favorite additions",
			setupMock: func(mockDB *MockDB, mockAssoc *MockAssociation) {
				mockDB.On("Model", mock.Anything).Return(mockDB)
				mockDB.On("Association", "FavoritedBy").Return(mockAssoc)
				mockAssoc.On("Append", mock.Anything).Return(nil)
				mockDB.On("Save", mock.Anything).Return(mockDB)
			},
			expectedError:  nil,
			expectedCount:  5,
			concurrentTest: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			mockDB := new(MockDB)
			mockAssoc := new(MockAssociation)
			tt.setupMock(mockDB, mockAssoc)

			store := &ArticleStore{db: mockDB}
			article := &model.Article{FavoritesCount: 0}
			user := &model.User{}

			if tt.concurrentTest {
				var wg sync.WaitGroup
				for i := 0; i < 5; i++ {
					wg.Add(1)
					go func() {
						defer wg.Done()
						err := store.AddFavorite(article, user)
						assert.NoError(t, err)
					}()
				}
				wg.Wait()
			} else {
				err := store.AddFavorite(article, user)
				assert.Equal(t, tt.expectedError, err)
			}

			assert.Equal(t, tt.expectedCount, article.FavoritesCount)

			mockDB.AssertExpectations(t)
			mockAssoc.AssertExpectations(t)
		})
	}
}
